  start_round: startRoundPayloadSchema,
  vote_rematch: voteRematchPayloadSchema,
  request_snapshot: requestSnapshotPayloadSchema,
  ping: pingPayloadSchema,
  seat_spectator: seatSpectatorPayloadSchema,
  chat_text: chatTextPayloadSchema,
  quick_chat: quickChatPayloadSchema,
  emote: emotePayloadSchema,
  play_card: playCardPayloadSchema,
  take_hand: takeHandPayloadSchema,
  cancel_take: cancelTakePayloadSchema,
  table_state: tableStatePayloadSchema,
  rules_changed: rulesChangedPayloadSchema,
  presence: presencePayloadSchema,
  host_changed: hostChangedPayloadSchema,
  table_closed: tableClosedPayloadSchema,
  error: errorPayloadSchema,
  snapshot: snapshotPayloadSchema,
  pong: pongPayloadSchema,
  chat: chatPayloadSchema,
  quick_chat_sent: quickChatSentPayloadSchema,
  emote_sent: emoteSentPayloadSchema,
  round_start: roundStartPayloadSchema,
  turn_start: turnStartPayloadSchema,
  move_applied: moveAppliedPayloadSchema,
  move_rejected: moveRejectedPayloadSchema,
  trick_resolved: trickResolvedPayloadSchema,
  pickup: pickupPayloadSchema,
  escape: escapePayloadSchema,
